import{_ as l,a0 as o,w as d,s as r,ao as p,I as n,x as s,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Bat：一種具有語法高亮和 Git 集成的 Cat 類命令 | LCTT x X-CMD","titleTemplate":false,"description":"Bat：一種具有語法高亮和 Git 集成的 Cat 類命令 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bat：一種具有語法高亮和 Git 集成的 Cat 類命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bat：一種具有語法高亮和 Git 集成的 Cat 類命令 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180828 A Cat Clone With Syntax Highlighting And Git Integration","title":"Bat：一種具有語法高亮和 Git 集成的 Cat 類命令","tag":"201809","desc":""},"relativePath":"201809/20180828 A Cat Clone With Syntax Highlighting And Git Integration.md","filePath":"[post].md"}'),h={name:"201809/20180828 A Cat Clone With Syntax Highlighting And Git Integration.md"};function g(c,t,b,u,k,m){const a=o("Link");return d(),r("div",null,[t[23]||(t[23]=p('<h1 id="bat-一種具有語法高亮和-git-集成的-cat-類命令" tabindex="-1">Bat：一種具有語法高亮和 Git 集成的 Cat 類命令 <a class="header-anchor" href="#bat-一種具有語法高亮和-git-集成的-cat-類命令" aria-label="Permalink to “Bat：一種具有語法高亮和 Git 集成的 Cat 類命令”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/Bat-command-720x340.png" alt=""></p><p>在類 UNIX 系統中，我們使用 <code>cat</code> 命令去打印和連接文件。使用 <code>cat</code> 命令，我們能將文件目錄打印到到標準輸出，合成幾個文件為一個目標文件，還有追加幾個文件到目標文件中。今天，我偶然發現一個具有相似作用的命令叫做 “Bat” ，它是 <code>cat</code> 命令的一個克隆版，具有一些例如語法高亮、 Git 集成和自動分頁等非常酷的特性。在這個簡略指南中，我們將講述如何在 Linux 中安裝和使用 <code>bat</code> 命令。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>Bat 可以在 Arch Linux 的默認軟件源中獲取。 所以你可以使用 <code>pacman</code> 命令在任何基於 arch 的系統上來安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S bat</span></span></code></pre></div>',6)),n("p",null,[t[1]||(t[1]=s("在 Debian、Ubuntu、Linux Mint 等系統中，從其",-1)),i(a,{href:"https://github.com/sharkdp/bat/releases"},{default:e(()=>[...t[0]||(t[0]=[s("發佈頁面",-1)])]),_:1}),t[2]||(t[2]=s("下載 ",-1)),t[3]||(t[3]=n("strong",null,".deb",-1)),t[4]||(t[4]=s(" 文件，然後用下面的命令來安裝。",-1))]),t[24]||(t[24]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gdebi</span></span>
<span class="line"><span>$ sudo gdebi bat_0.5.0_amd64.deb</span></span></code></pre></div><p>對於其他系統，你也許需要從軟件源編譯並安裝。確保你已經安裝了 Rust 1.26 或者更高版本。</p><p>然後運行以下命令來安裝 Bat：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cargo install bat</span></span></code></pre></div>`,4)),n("p",null,[t[6]||(t[6]=s("或者，你可以從 ",-1)),i(a,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:e(()=>[...t[5]||(t[5]=[s("Linuxbrew",-1)])]),_:1}),t[7]||(t[7]=s(" 軟件包管理中來安裝它。",-1))]),t[25]||(t[25]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install bat</span></span></code></pre></div><h3 id="bat-命令的使用" tabindex="-1">bat 命令的使用 <a class="header-anchor" href="#bat-命令的使用" aria-label="Permalink to “bat 命令的使用”">​</a></h3><p><code>bat</code> 命令的使用與 <code>cat</code> 命令的使用非常相似。</p><p>使用 <code>bat</code> 命令創建一個新的文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat &gt; file.txt</span></span></code></pre></div><p>使用 <code>bat</code> 命令來查看文件內容，只需要:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat file.txt</span></span></code></pre></div><p>你能同時查看多個文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat file1.txt file2.txt</span></span></code></pre></div><p>將多個文件的內容合併至一個單獨文件中:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat file1.txt file2.txt file3.txt &gt; document.txt</span></span></code></pre></div><p>就像我之前提到的那樣，除了瀏覽和編輯文件以外，<code>bat</code> 命令有一些非常酷的特性。</p><p><code>bat</code> 命令支持大多數編程和標記語言的<ruby>語法高亮<rt>syntax highlighting</rt></ruby>。比如，下面這個例子。我將使用 <code>cat</code> 和 <code>bat</code> 命令來展示 <code>reverse.py</code> 的內容。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-and-cat-command-output-comparison.png" alt=""></p><p>你注意到區別了嗎？ <code>cat</code> 命令以純文本格式顯示文件的內容，而 <code>bat</code> 命令顯示了語法高亮和整齊的文本對齊格式。更好了不是嗎？</p><p>如果你只想顯示行號（而沒有表格）使用 <code>-n</code> 標記。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat -n reverse.py</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-command-output-3.png" alt=""></p><p>另一個 <code>bat</code> 命令中值得注意的特性是它支持<ruby>自動分頁<rt>automatic paging</rt></ruby>。 它的意思是當文件的輸出對於屏幕來説太大的時候，<code>bat</code> 命令自動將自己的輸出內容傳輸到 <code>less</code> 命令中，所以你可以一頁一頁的查看輸出內容。</p><p>讓我給你看一個例子，使用 <code>cat</code> 命令查看跨多個頁面的文件的內容時，提示符會快速跳至文件的最後一頁，你看不到內容的開頭和中間部分。</p><p>看一下下面的輸出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/cat-command-output.png" alt=""></p><p>正如你所看到的，<code>cat</code> 命令顯示了文章的最後一頁。</p><p>所以你也許需要去將使用 <code>cat</code> 命令的輸出傳輸到 <code>less</code> 命令中去從開頭一頁一頁的查看內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat reverse.py | less</span></span></code></pre></div><p>現在你可以使用回車鍵去一頁一頁的查看輸出。然而當你使用 <code>bat</code> 命令時這些都是不必要的。<code>bat</code> 命令將自動傳輸跨越多個頁面的文件的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat reverse.py</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-command-output-1.png" alt=""></p><p>現在按下回車鍵去往下一頁。</p><p><code>bat</code> 命令也支持 <ruby>Git 集成<rt><strong>GIT integration</strong></rt></ruby>，這樣您就可以輕鬆查看/編輯 Git 存儲庫中的文件。 它與 Git 連接可以顯示關於索引的修改。（看左欄）</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-command-output-2.png" alt=""></p><h3 id="定製-bat" tabindex="-1">定製 Bat <a class="header-anchor" href="#定製-bat" aria-label="Permalink to “定製 Bat”">​</a></h3><p>如果你不喜歡默認主題，你也可以修改它。Bat 同樣有修改它的選項。</p><p>若要顯示可用主題，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat --list-themes</span></span>
<span class="line"><span>1337</span></span>
<span class="line"><span>DarkNeon</span></span>
<span class="line"><span>Default</span></span>
<span class="line"><span>GitHub</span></span>
<span class="line"><span>Monokai Extended</span></span>
<span class="line"><span>Monokai Extended Bright</span></span>
<span class="line"><span>Monokai Extended Light</span></span>
<span class="line"><span>Monokai Extended Origin</span></span>
<span class="line"><span>TwoDark</span></span></code></pre></div><p>要使用其他主題，例如 TwoDark，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat --theme=TwoDark file.txt</span></span></code></pre></div><p>如果你想永久改變主題，在你的 shells 啓動文件中加入 <code>export BAT_THEME=&quot;TwoDark&quot;</code>。</p><p><code>bat</code> 還可以選擇修改輸出的外觀。使用 <code>--style</code> 選項來修改輸出外觀。僅顯示 Git 的更改和行號但不顯示網格和文件頭，請使用 <code>--style=numbers,changes</code>。</p><p>更多詳細信息，請參閲 Bat 項目的 GitHub 庫（鏈接在文末）。</p><p>最好，這就是目前的全部內容了。希望這篇文章會幫到你。更多精彩文章即將到來，敬請關注！</p><p>乾杯！</p><hr>`,43)),n("p",null,[t[9]||(t[9]=s("via: ",-1)),i(a,{href:"https://www.ostechnix.com/bat-a-cat-clone-with-syntax-highlighting-and-git-integration/"},{default:e(()=>[...t[8]||(t[8]=[s("https://www.ostechnix.com/bat-a-cat-clone-with-syntax-highlighting-and-git-integration/",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=s("作者：",-1)),i(a,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...t[10]||(t[10]=[s("SK",-1)])]),_:1}),t[15]||(t[15]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[11]||(t[11]=[s("lujun9972",-1)])]),_:1}),t[16]||(t[16]=s(" 譯者：",-1)),i(a,{href:"https://github.com/z52527"},{default:e(()=>[...t[12]||(t[12]=[s("z52527",-1)])]),_:1}),t[17]||(t[17]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[18]||(t[18]=[s("LCTT",-1)])]),_:1}),t[21]||(t[21]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...t[19]||(t[19]=[s("Linux中國",-1)])]),_:1}),t[22]||(t[22]=s(" 榮譽推出",-1))])])}const y=l(h,[["render",g]]);export{C as __pageData,y as default};
